(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const yamlPath = process.env.YAML_PATH;
  const jsonPath = process.env.JSON_PATH;
  if (!yamlPath) throw new Error('Missing required env var YAML_PATH');
  if (!existsSync(yamlPath)) throw new Error('YAML file does not exist: ' + yamlPath);
  const content = readFileSync(yamlPath, 'utf8');
  globalThis.yamlContent = content;
  globalThis.jsonPath = jsonPath; // may be undefined
})();

(async () => {
  const { load } = await import('js-yaml');
  const yamlStr = globalThis.yamlContent;
  const obj = load(yamlStr);
  globalThis.parsedObj = obj;
})();

(async () => {
  const result = { json: JSON.stringify(globalThis.parsedObj) };
  if (globalThis.jsonPath) {
    const { writeFileSync } = await import('node:fs');
    writeFileSync(globalThis.jsonPath, result.json, 'utf8');
  }
  console.log(JSON.stringify(result));
})();
